$("#canvas")?.addEventListener("pointerdown",e=>{const canvas=$("#canvas") as HTMLElement;if(!canvas.classList.contains("drawing"))return;const rect=canvas.getBoundingClientRect();const path=document.createElementNS("http://www.w3.org/2000/svg","path");const x=(e as PointerEvent).clientX-rect.left+canvas.scrollLeft,y=(e as PointerEvent).clientY-rect.top+canvas.scrollTop;path.setAttribute("d","M "+x+" "+y);path.setAttribute("stroke","#d8c4f4");path.setAttribute("stroke-width","3");path.setAttribute("fill","none");path.setAttribute("stroke-linecap","round");$("#connectors")!.append(path);const move=(ev:PointerEvent)=>{const xx=ev.clientX-rect.left+canvas.scrollLeft,yy=ev.clientY-rect.top+canvas.scrollTop;path.setAttribute("d",path.getAttribute("d")+" L "+xx+" "+yy)};const up=()=>{window.removeEventListener("pointermove",move);window.removeEventListener("pointerup",up);const boardId=canvas.dataset.board||"";const drawing=create("boardText","Freehand drawing",boardId);drawing.metadata={type:"drawing",path:path.getAttribute("d")||"",stroke:"#d8c4f4"};put(drawing)};window.addEventListener("pointermove",move);window.addEventListener("pointerup",up)});
