$("#paste-template")?.addEventListener("click",()=>{
 const overlay=document.createElement("div");overlay.className="template-overlay";
 overlay.innerHTML='<section class="template-dialog"><div class="module-head"><div><span class="eyebrow">TEMPLATE BUILDER</span><h2>Create from pasted outline</h2><p>One line creates one item. Indentation nests sections, subsections and individual aspects.</p></div><button type="button" id="close-template">Close</button></div><label class="template-name">Template name<input id="template-name" placeholder="e.g. Fantasy kingdom"></label><div class="template-builder-grid"><label>Paste your outline<textarea id="template-source" spellcheck="false" placeholder="Geography&#10;  Natural features&#10;    Mountains&#10;    Rivers&#10;  Settlements&#10;    Capital city&#10;    Villages&#10;Culture&#10;  Society&#10;    Social hierarchy&#10;    Customs"></textarea></label><div class="template-preview-pane"><b>Live structure preview</b><p class="muted">Indentation determines nesting. Blank lines are ignored.</p><div id="template-preview" class="template-preview"><span class="muted">Your structure will appear here.</span></div></div></div><div class="template-dialog-foot"><span id="template-count" class="muted">0 items · 0 aspects</span><button type="button" id="save-pasted-template">Create template</button></div></section>';
 document.body.append(overlay);
 const source=overlay.querySelector<HTMLTextAreaElement>("#template-source")!;
 const preview=overlay.querySelector<HTMLElement>("#template-preview")!;
 const count=overlay.querySelector<HTMLElement>("#template-count")!;
 const countNodes=(nodes:TemplateNode[]):number=>nodes.reduce((n,node)=>n+1+countNodes(node.children),0);
 const update=()=>{const tree=parseTemplateOutline(source.value);const leaves=templateLeaves(tree);preview.innerHTML=tree.length?templatePreview(tree):'<span class="muted">Your structure will appear here.</span>';count.textContent=countNodes(tree)+" items · "+leaves.length+" aspects"};
 source.addEventListener("input",update);
 overlay.querySelector("#close-template")!.addEventListener("click",()=>overlay.remove());
 overlay.addEventListener("click",e=>{if(e.target===overlay)overlay.remove()});
 overlay.querySelector("#save-pasted-template")!.addEventListener("click",async()=>{
  const title=(overlay.querySelector<HTMLInputElement>("#template-name")!.value||"").trim();const tree=parseTemplateOutline(source.value);
  if(!title){alert("Give this template a name.");return}if(!tree.length){alert("Paste at least one non-empty line.");return}
  const fields=templateLeaves(tree);const r=create("schema",title);r.body="Created from pasted outline";r.metadata={icon:"✧",fields,sections:tree,sourceFormat:"indented-outline",version:1};await put(r);overlay.remove();render();
 });
 source.focus();
});

