$("#add-table")?.addEventListener("click",async()=>{const name=ask("Table name");if(!name)return;const cols=ask("Columns as Name:TYPE (TEXT,CHECKBOX,DROPDOWN,ENTITY_LINK)","Name:TEXT,Status:DROPDOWN,Done:CHECKBOX").split(",").map(x=>({name:x.split(":")[0],type:x.split(":")[1]||"TEXT"}));const ownerName=ask("Attach table to Story Bible entity (optional exact name)");const owner=rows.find(x=>x.kind==="entity"&&x.title.toLowerCase()===ownerName.toLowerCase());const r=create("table",name,owner?.id);r.metadata={columns:cols,ownerEntityId:owner?.id||""};await put(r);render()});
document.querySelectorAll<HTMLElement>("[data-add-table-row]").forEach(b=>b.onclick=async()=>{const t=rows.find(x=>x.id===b.dataset.addTableRow);if(!t)return;const cells:Record<string,any>={};const vals=(t.metadata?.columns||[]).map((c:any)=>{let value:any;if(c.type==="CHECKBOX")value=confirm("Check "+c.name+"?");else if(c.type==="DROPDOWN"){const options=ask(c.name+" options (comma separated)","Draft,In progress,Done");value=ask(c.name+" · choose or type a value",options.split(",")[0]||"")}else if(c.type==="ENTITY_LINK"){const name=ask(c.name+" · linked entity name");value=rows.find(x=>x.kind==="entity"&&x.title.toLowerCase()===name.toLowerCase())?.id||name}else value=ask(c.name);cells[c.name]=value;return c.name+": "+(typeof value==="boolean"?(value?"☑":"☐"):String(value))});const r=create("tableRow",vals.join(" | "),t.id);r.body=vals.join(" | ");r.metadata={cells};await put(r);render()});
