$("#share-summary")?.addEventListener("click",async()=>{const summary="Ink & Quill progress · "+rows.filter(r=>r.kind==="scene").reduce((n,r)=>n+words(plain(r.body||"")),0)+" manuscript words";if(navigator.share)await navigator.share({title:"Writing progress",text:summary});else if(navigator.clipboard)await navigator.clipboard.writeText(summary);else alert(summary)});$("#enable-reminders")?.addEventListener("click",async()=>{if(!("Notification"in window))return alert("This browser does not support notifications.");const permission=await Notification.requestPermission();if(permission==="granted"){const hour=Number(ask("Reminder hour (0–23)","19"));const ms=((hour-new Date().getHours()+24)%24)*3600000;window.setTimeout(()=>new Notification("Time to write",{body:"Your world is waiting. Open Ink & Quill for your writing session."}),ms);alert("One reminder scheduled while this app remains open.")}});$("#log-session")?.addEventListener("click",async()=>{const n=Number(ask("Words written this session","500"));if(Number.isFinite(n)&&n>=0){const r=create("log",new Date().toISOString().slice(0,10));r.metadata={words:n,date:new Date().toISOString().slice(0,10),time:now()};r.body=ask("Session notes / custom text");await put(r);render()}});
$("#sprint-start")?.addEventListener("click",()=>{sprintSeconds=Math.max(60,Number(($("#sprint-minutes") as HTMLInputElement).value)*60);sprintTarget=Math.max(1,Number(($("#sprint-target") as HTMLInputElement).value));sprintStart=now();sprintStartWords=words(($("#sprint-draft") as HTMLTextAreaElement|null)?.value||"");clearInterval(sprintTimer);sprintTimer=window.setInterval(()=>{const elapsed=Math.floor((now()-sprintStart)/1000);const remaining=Math.max(0,sprintSeconds-elapsed);$("#sprint-clock")!.textContent=formatTime(remaining);const currentWords=words(($("#sprint-draft") as HTMLTextAreaElement|null)?.value||"")-sprintStartWords;const wpm=Math.round(currentWords/Math.max(1,elapsed/60));$("#sprint-words")!.textContent=String(Math.max(0,currentWords));$("#sprint-wpm")!.textContent=String(Math.max(0,wpm));$("#sprint-progress")!.textContent=Math.min(100,Math.round(currentWords/sprintTarget*100))+"%";($("#sprint-bar") as HTMLProgressElement).value=Math.max(0,currentWords);if(remaining===0)clearInterval(sprintTimer)},1000)});
$("#sprint-pause")?.addEventListener("click",()=>clearInterval(sprintTimer));
$("#sprint-finish")?.addEventListener("click",async()=>{clearInterval(sprintTimer);const delta=Math.max(0,words(($("#sprint-draft") as HTMLTextAreaElement|null)?.value||"")-sprintStartWords);const r=create("log",new Date().toISOString().slice(0,10));r.metadata={words:delta,date:new Date().toISOString().slice(0,10),time:now()};r.body=($("#sprint-notes") as HTMLTextAreaElement|null)?.value||"";await put(r);alert("Sprint logged: "+delta+" words.");render()});
